<?php
declare(strict_types=1); namespace Neok\Pay\Http;
use DateTimeImmutable; use Neok\Pay\DTO\Payment; use Neok\Pay\Enums\PaymentStatus; use Neok\Pay\Exceptions\{ApiException,AuthenticationException,ConflictException,NotFoundException,RateLimitException,ValidationException}; use Psr\Http\Message\ResponseInterface;
final class ResponseParser {
 /** @return array<string,mixed> */ public function json(ResponseInterface $response): array { try { $value=json_decode((string)$response->getBody(),true,512,JSON_THROW_ON_ERROR); } catch(\JsonException){ throw new ApiException('NEOK Pay returned malformed JSON.',$response->getStatusCode()); } if(!is_array($value)) throw new ApiException('NEOK Pay returned an unexpected JSON response.',$response->getStatusCode()); return $value; }
 /** @param array<string,mixed> $payload */ public function payment(array $payload): Payment { foreach(['id','reference','amount','currency','status','created_at'] as $key) if(!is_string($payload[$key]??null)) throw new ApiException('NEOK Pay returned an invalid payment response.',200); try{$status=PaymentStatus::from($payload['status']);$created=new DateTimeImmutable($payload['created_at']);$paid=isset($payload['paid_at'])&&$payload['paid_at']!==null?new DateTimeImmutable((string)$payload['paid_at']):null;}catch(\ValueError|\Exception){throw new ApiException('NEOK Pay returned an invalid payment response.',200);} return new Payment($payload['id'],$payload['reference'],$payload['amount'],$payload['currency'],$status,$created,$paid); }
 /** @return never */ public function error(ResponseInterface $response): void { $body=$this->json($response);$error=is_array($body['error']??null)?$body['error']:[];$message=is_string($error['message']??null)?$error['message']:'NEOK Pay request failed.';$code=is_string($error['code']??null)?$error['code']:null;$details=is_array($error['details']??null)?$error['details']:[];$class=match($response->getStatusCode()){401=>AuthenticationException::class,404=>NotFoundException::class,409=>ConflictException::class,422=>ValidationException::class,429=>RateLimitException::class,default=>ApiException::class};throw new $class($message,$response->getStatusCode(),$code,$details); }
}
